    },
    {
      "claim": "Norverapamil (desmethyl verapamil) sustained-release records report F of 49±14% fasted and 34±12% fed (C09, C21), supporting that verapamil-like scaffolds can exceed 20%.",
      "card_ids": ["C09", "C21"]
    },
    {
      "claim": "No transferable direct low-F (<20%) record exists for the query; the only sub-20% values are in unrelated scaffolds/species (mouse venlafaxine 11.6%, rat sulpiride 15%, dog tramadol SR 10%; C32, C34, C43) and are not applicable.",
      "card_ids": ["C32", "C34", "C43"]
    }
  ],
